<?php declare(strict_types=1); namespace App\Core\Middleware; use App\Core\Auth; use App\Core\Request; use App\Core\Response; use App\Core\ForbiddenException; final class RoleMiddleware { public function __construct(private readonly Auth $auth){} public function handle(Request $request,\Closure $next,?string $role=null):Response{if($role!==null&&!$this->auth->hasRole($role))throw new ForbiddenException('Role not permitted.');return $next($request);} }